      b = (await canvas.boundingBox())!,
      at = (x: number, y: number) => ({ x: b.x + (x + 175) * b.width / 350, y: b.y + (y + 175) * b.height / 350 }),
      move = async (x: number, y: number) => { const p = at(x, y); await page.mouse.move(p.x, p.y); },
