    expect(respawned[1]).toMatchObject({ key: respawned[0].twin, twin: '1_mc', x: -17, y: -6 });
    await move(-17, 6);
    await page.mouse.down();
    await move(-16.75, 6);
    await page.mouse.up();
    const quarter = await parts();
    for (const p of quarter) expect(p.x).toBeCloseTo(-16.75, 4);
    expect(quarter.map(p => p.y)).toEqual([6, -6]);
    await expect(page.getByRole('status')).toContainText('Selected parts (2)');
    // A delivered move event with unchanged coordinates still runs _-5M,
    // suppresses CLICK selection toggling and records an accepted no-op snapshot.
    await page.mouse.down();
    const unchanged = at(-16.75, 6);
    await canvas.dispatchEvent('pointermove', { clientX: unchanged.x, clientY: unchanged.y, pointerId: 1, bubbles: true });
    await page.mouse.up();
    expect(await parts()).toEqual(quarter);
    await expect(page.getByRole('status')).toContainText('Selected parts (2)');
    await page.getByRole('button', { name: 'Undo', exact: true }).click();
    expect(await parts()).toEqual(quarter);
    await page.getByRole('button', { name: 'Undo', exact: true }).click();
    expect(await parts()).toEqual(respawned);
    await page.locator('.creator').screenshot({ path: `test-results/${native ? 'native' : 'mock'}-creator-drag.png` });
